const paths={lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',reset:'<path d="M3 10a9 9 0 1 1 1 8M3 3v7h7"/>',sliders:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',check:'<path d="m5 12 4 4L19 6"/>',sparkle:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',bulb:'<path d="M8 16a7 7 0 1 1 8 0v3H8zM9 22h6m-5-8v5m4-5v5"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.check}</svg>`;
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));

const {calculateLoan,principalValue,rankOffers,defaultOffers}=await import('./calculator.mjs');
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',minimumFractionDigits:0,maximumFractionDigits:0}).format(n);
const state={principal:'1000000',offers:defaultOffers(),results:[],rank:null};let nextId=3;
const nameFor=o=>o.name.trim()||`Offer ${o.id}`;
function fields(o){const numeric=(key,label,suffix,min,max,step='1')=>`<label class="field"><span>${label}</span><div class="input-box"><input type="number" data-field="${key}" value="${esc(o[key])}" min="${min}" max="${max}" step="${step}" aria-label="${label} for offer ${o.id}"><span>${suffix}</span></div></label>`;return numeric('rate','Interest rate','% p.a.',0,60,'0.05')+numeric('months','Tenure','months',1,480)+`<div class="fields-pair"><label class="field"><span>Processing fee</span><div class="input-box"><input type="number" data-field="fee" min="0" value="${esc(o.fee)}" step="0.01" aria-label="Processing fee for offer ${o.id}"><select data-field="feeType" aria-label="Fee unit for offer ${o.id}"><option value="rupees" ${o.feeType==='rupees'?'selected':''}>₹</option><option value="percent" ${o.feeType==='percent'?'selected':''}>%</option></select></div></label>${numeric('other','Other charges','₹',0,100000000,'0.01')}</div>`}
function renderCards(){
 $('offer-grid').className=`offer-grid ${state.offers.length===2?'two':state.offers.length===4?'four':''}`;
 $('offer-grid').innerHTML=state.offers.map(o=>`<article class="offer-card" id="offer-${o.id}" data-id="${o.id}"><div class="offer-header"><span class="offer-letter">${o.id}</span><input class="offer-name" data-field="name" type="text" maxlength="35" value="${esc(o.name)}" aria-label="Name for offer ${o.id}"><button class="remove-offer" data-remove="${o.id}" aria-label="Remove offer ${o.id}" ${state.offers.length===2?'disabled':''}>×</button></div><div class="offer-inputs">${fields(o)}</div><p class="field-error offer-error" role="alert" hidden></p><div class="emi-block"><span>MONTHLY EMI</span><strong data-result="emi">—</strong><small>Estimated monthly payment</small></div><div class="offer-results"><div class="result-line"><span>Total interest</span><strong data-result="interest">—</strong></div><div class="result-line"><span>Upfront fees</span><strong data-result="upfrontFees">—</strong></div><div class="result-line total"><span>Total repayment</span><strong data-result="total">—</strong></div></div><div class="offer-badge"></div></article>`).join('');
 $('offer-count').textContent=`${state.offers.length} offers`;$('add-offer').disabled=state.offers.length===4;updateResults();
}
function updateResults(){
 let principalError='';try{principalValue(state.principal)}catch(e){principalError=e.message}
 $('principal-error').hidden=!principalError;$('principal-error').textContent=principalError;$('loan-amount').setAttribute('aria-invalid',String(!!principalError));
 const p=Number(state.principal);$('principal-caption').textContent=principalError?'₹10,000 to ₹10 crore':p>=10000000?`${+(p/10000000).toFixed(3)} crore rupees`:p>=100000?`${+(p/100000).toFixed(3)} lakh rupees`:money(p);
 if(!principalError)$('amount-range').value=String(Math.min(Math.max(p,10000),5000000));
 document.querySelectorAll('[data-amount]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.amount)===p&&!principalError));
 state.results=state.offers.map(o=>{try{return {value:calculateLoan(state.principal,o)}}catch(e){return {error:e.message}}});
 state.rank=rankOffers(state.results.map(r=>r.value));
 state.offers.forEach((o,i)=>{const card=$('offer-'+o.id),r=state.results[i],best=state.rank?.cheapest.includes(i),low=state.rank?.lowestEmi.includes(i);card.classList.toggle('best',!!best);const error=card.querySelector('.offer-error');error.hidden=!r.error||!!principalError;error.textContent=r.error||'';card.querySelectorAll('[data-result]').forEach(el=>el.textContent=r.value?money(r.value[el.dataset.result]):'—');const badge=card.querySelector('.offer-badge');badge.className=`offer-badge ${best?'winner':''}`;badge.innerHTML=best?`${icon('check')}${state.rank.cheapest.length>1?'Tied lowest total cost':'Lowest total cost'}`:low?`${icon('check')}${state.rank.lowestEmi.length>1?'Tied lowest monthly EMI':'Lowest monthly EMI'}`:'Includes principal, interest & fees';});
 renderVerdict();renderBreakdown();renderTable();
}
function renderVerdict(){
 const rank=state.rank;let title='Complete each offer to compare.',copy='Enter valid amounts, interest rates, tenure and charges to see the comparison.',saving='';
 if(rank){
  if(rank.cheapest.length>1){title=`${rank.cheapest.length} offers share the lowest total cost.`;copy=`${rank.cheapest.map(i=>nameFor(state.offers[i])).join(' and ')} total ${money(rank.minTotal)} each, rounded to the nearest rupee. Compare their monthly payments and terms.`}
  else{const best=rank.cheapest[0],winner=state.offers[best],r=state.results[best].value;title=`${nameFor(winner)} has the lowest total cost.`;copy=`${money(r.emi)} per month for ${r.months} months, plus ${money(r.upfrontFees)} in upfront fees.`;saving=`<div class="savings-stat"><strong>${money(rank.savings)}</strong><span>less than the next cheapest offer</span></div>`}
  const differing=rank.lowestEmi.find(i=>!rank.cheapest.includes(i));if(differing!==undefined&&rank.minEmi<Math.round(state.results[rank.cheapest[0]].value.emi))copy+=` ${nameFor(state.offers[differing])} has a lower EMI, but costs more overall.`;
 }
 $('verdict').innerHTML=`<div class="verdict-icon">${icon('sparkle')}</div><div><span class="verdict-kicker">THE BIGGER PICTURE</span><h2>${esc(title)}</h2><p>${esc(copy)}</p></div>${saving}`;
}
function renderBreakdown(){
 const results=state.results.map(r=>r.value);if(!state.rank){$('breakdown-chart').innerHTML='<p class="chart-empty">Complete the offers to see their cost breakdown.</p>';return}
 const max=Math.max(...results.map(r=>r.total));
 $('breakdown-chart').innerHTML=results.map((r,i)=>`<div class="bar-row"><span class="bar-name" title="${esc(nameFor(state.offers[i]))}">${esc(nameFor(state.offers[i]))}</span><div class="bar-track" role="img" aria-label="${esc(nameFor(state.offers[i]))}: principal ${esc(money(r.principal))}, interest ${esc(money(r.interest))}, fees ${esc(money(r.upfrontFees))}"><span class="principal-key" style="width:${r.principal/max*100}%" title="Principal ${esc(money(r.principal))}"></span><span class="interest-key" style="width:${r.interest/max*100}%" title="Interest ${esc(money(r.interest))}"></span><span class="fees-key" style="width:${r.upfrontFees/max*100}%" title="Upfront fees ${esc(money(r.upfrontFees))}"></span></div><strong class="bar-value">${esc(money(r.total))}</strong></div>`).join('');
}
function renderTable(){
 const table=$('comparison-table');table.querySelector('thead').innerHTML=`<tr><th scope="col">At a glance</th>${state.offers.map(o=>`<th scope="col">${o.id} · ${esc(nameFor(o))}</th>`).join('')}</tr>`;
 const fields=[['Loan amount','principal',money],['Interest rate','annualRate',n=>`${n}% p.a.`],['Tenure','months',n=>`${n} months`],['Monthly EMI','emi',money],['Total interest','interest',money],['Processing fee','processingFee',money],['Other upfront charges','other',money],['Total upfront fees','upfrontFees',money],['All monthly payments','installments',money],['Total repayment, including fees','total',money],['Cost of borrowing (interest + fees)','cost',money]];
 table.querySelector('tbody').innerHTML=fields.map(([label,key,format])=>`<tr><th scope="row">${label}</th>${state.results.map((r,i)=>`<td class="${state.rank?.cheapest.includes(i)&&['total','cost'].includes(key)?'best-cell':''}">${r.value?esc(format(r.value[key])):'—'}</td>`).join('')}</tr>`).join('');
}
function setPrincipal(value){state.principal=String(value);$('loan-amount').value=state.principal;updateResults()}
$('loan-amount').addEventListener('input',e=>{state.principal=e.target.value;updateResults()});$('amount-range').addEventListener('input',e=>setPrincipal(e.target.value));document.querySelectorAll('[data-amount]').forEach(b=>b.addEventListener('click',()=>setPrincipal(b.dataset.amount)));
$('offer-grid').addEventListener('input',e=>{const key=e.target.dataset.field;if(!key)return;const card=e.target.closest('[data-id]'),o=state.offers.find(o=>o.id===card.dataset.id);o[key]=e.target.value;updateResults()});
$('offer-grid').addEventListener('click',e=>{const button=e.target.closest('[data-remove]');if(!button||state.offers.length<=2)return;state.offers=state.offers.filter(o=>o.id!==button.dataset.remove);renderCards()});
$('add-offer').addEventListener('click',()=>{if(state.offers.length>=4)return;const id=['A','B','C','D'].find(id=>!state.offers.some(o=>o.id===id));state.offers.push({id,name:`Offer ${id}`,rate:'10',months:'36',fee:'0',feeType:'rupees',other:'0'});renderCards();$('offer-'+id).querySelector('.offer-name').focus()});
$('reset-button').addEventListener('click',()=>{state.principal='1000000';state.offers=defaultOffers();nextId=3;$('loan-amount').value=state.principal;renderCards()});
['method-button','footer-method'].forEach(id=>$(id).addEventListener('click',()=>$('method-dialog').showModal()));$('close-method').addEventListener('click',()=>$('method-dialog').close());$('method-dialog').addEventListener('click',e=>{const d=e.currentTarget,r=d.getBoundingClientRect();if(e.target===d&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))d.close()});
renderCards();
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const summary=()=>({currency:'INR',principal:state.principal,valid:!!state.rank,offers:state.offers.map((o,i)=>({name:nameFor(o),...state.results[i]})),lowestTotalOfferNames:state.rank?.cheapest.map(i=>nameFor(state.offers[i]))||[]});
 const tools=[{name:'read_loan_comparison',title:'Read loan comparison',description:'Read the displayed loan estimates, fees and lowest-total-cost offers. These are calculator estimates, not lender quotes.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input&&Object.keys(input).length)throw new Error('No arguments are accepted.');return summary()}},{name:'set_loan_comparison',title:'Set loan comparison',description:'Replace this browser’s calculator inputs with two to four offers and update the estimates. Does not apply for a loan or contact a lender.',inputSchema:{type:'object',additionalProperties:false,required:['principal','offers'],properties:{principal:{type:'number',minimum:10000,maximum:100000000},offers:{type:'array',minItems:2,maxItems:4,items:{type:'object',additionalProperties:false,required:['name','rate','months','fee','feeType','other'],properties:{name:{type:'string',maxLength:35},rate:{type:'number',minimum:0,maximum:60},months:{type:'integer',minimum:1,maximum:480},fee:{type:'number',minimum:0},feeType:{type:'string',enum:['rupees','percent']},other:{type:'number',minimum:0}}}}}},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.principal!=='number'||!Array.isArray(input.offers)||input.offers.length<2||input.offers.length>4)throw new Error('Provide a principal and two to four offers.');const converted=input.offers.map((o,i)=>{if(!o||typeof o.name!=='string'||o.name.length>35||['rate','months','fee','other'].some(k=>typeof o[k]!=='number'))throw new Error('Each offer needs a name and numeric loan terms.');calculateLoan(input.principal,o);return {...o,id:String.fromCharCode(65+i),rate:String(o.rate),months:String(o.months),fee:String(o.fee),other:String(o.other)}});state.principal=String(input.principal);state.offers=converted;nextId=converted.length;$('loan-amount').value=state.principal;renderCards();return summary()}}];
 for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
